;(function () {
  const THEMES     = ['flip', 'mod', 'retro']
  const THEME_FILE = { flip: 'clock.html', mod: 'clock.html', retro: 'clock-retro.html' }

  const fname      = window.location.pathname.split('/').pop() || 'clock.html'
  const isRetro    = fname === 'clock-retro.html'
  const isSettings = fname === 'clock-settings.html'

  let currentTheme = isRetro ? 'retro' : (localStorage.getItem('clock-theme') || 'flip')

  // ── CSS — the bottom bar only ─────────────────────────────
  const style = document.createElement('style')
  style.textContent = `
    .cc-bar { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 10px 24px 12px;
      background: transparent; z-index: 300; user-select: none; margin-top: 24px; }
    .cc-row { display: flex; align-items: center; gap: 16px; }
    .cc-arrow, .cc-scale-btn { width: 32px; height: 32px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.15);
      background: transparent; color: rgba(255,255,255,0.5); font-size: 18px; line-height: 1; cursor: pointer;
      display: flex; align-items: center; justify-content: center; transition: color .15s, border-color .15s; font-family: inherit; }
    .cc-arrow:hover, .cc-scale-btn:hover { color: #fff; border-color: rgba(255,255,255,0.6); }
    .cc-name { font-size: 16px; font-weight: bold; letter-spacing: .1em; text-transform: uppercase;
      color: rgba(255,255,255,0.7); min-width: 48px; text-align: center; }
    .cc-scale-val { font-size: 15px; color: rgba(255,255,255,0.4); min-width: 32px; text-align: center; font-family: monospace; }
  `
  document.head.appendChild(style)

  // ── the bottom bar — theme picker + zoom ──────────────────
  const bar = document.createElement('div')
  bar.className = 'cc-bar'
  bar.innerHTML = `
    <div class="cc-row">
      <button class="cc-arrow" id="cc-prev">&#8249;</button>
      <div class="cc-name" id="cc-name">${currentTheme}</div>
      <button class="cc-arrow" id="cc-next">&#8250;</button>
    </div>
    <div class="cc-row">
      <button class="cc-scale-btn" id="cc-dn">&#8722;</button>
      <div class="cc-scale-val" id="cc-val">1.0</div>
      <button class="cc-scale-btn" id="cc-up">+</button>
    </div>`
  // sit below the clock in document flow; the settings page has no .clock-layout → falls back to body
  const layout = document.querySelector('.clock-layout')
  if (layout) layout.after(bar); else document.body.appendChild(bar)

  // ── zoom (per page) ───────────────────────────────────────
  const SCALE_KEY = 'scale-' + fname, SCALE_STEP = 0.1, SCALE_MIN = 0.3, SCALE_MAX = 2.0
  let scale = parseFloat(localStorage.getItem(SCALE_KEY) || '1')
  function applyScale(s) {
    scale = Math.round(Math.max(SCALE_MIN, Math.min(SCALE_MAX, s)) * 10) / 10
    document.documentElement.style.setProperty('--clock-scale', scale)
    document.getElementById('cc-val').textContent = scale.toFixed(1)
    localStorage.setItem(SCALE_KEY, scale)
    const cl = document.querySelector('.clock-layout')
    if (cl) { const extra = Math.max(0, (scale - 1) * cl.offsetHeight); bar.style.marginTop = (24 + extra) + 'px' }
  }
  document.getElementById('cc-up').addEventListener('click', () => applyScale(scale + SCALE_STEP))
  document.getElementById('cc-dn').addEventListener('click', () => applyScale(scale - SCALE_STEP))
  applyScale(scale)

  // ── theme ─────────────────────────────────────────────────
  // on a clock page: flip/mod apply live (same clock.html, token swap); retro is its own page → navigate.
  // on the settings page: applies live via window.applyTheme (flip/mod only).
  const activeThemes = isSettings ? ['flip', 'mod'] : THEMES
  let activeTheme = isSettings ? (localStorage.getItem('clock-theme') || 'flip') : currentTheme
  function goTheme(t) {
    activeTheme = t
    document.getElementById('cc-name').textContent = t
    localStorage.setItem('clock-theme', t)
    localStorage.setItem('clock-theme-user', '1')   // (Sum 2026-07-14) a HUMAN pick — outranks the per-skin default forever
    if (isSettings) { if (typeof window.applyTheme === 'function') window.applyTheme(t); return }
    const target = THEME_FILE[t]
    if (target === fname) { currentTheme = t; if (typeof window.applyTheme === 'function') window.applyTheme(t) }
    else window.location.href = target
  }
  function stepTheme(dir) { const i = activeThemes.indexOf(activeTheme); goTheme(activeThemes[(i + dir + activeThemes.length) % activeThemes.length]) }
  document.getElementById('cc-prev').addEventListener('click', () => stepTheme(-1))
  document.getElementById('cc-next').addEventListener('click', () => stepTheme(+1))
})()
